<?php
$zipData = base64_decode('');
file_put_contents('deploy_ui_fixes.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_ui_fixes.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_ui_fixes.zip');
    echo '<h1>UI Fixes Deployed!</h1>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>